    int slot = -1;
    for (int i = 0; i < player->numTowns; i++) {
        if (player->townIds[i] == id)
            slot = i;
    }
    for (int j = slot; j < player->numTowns - 1; j++)
        player->townIds[j] = player->townIds[j + 1];
    player->townIds[player->numTowns - 1] = -1;
